def find_task_logs(doc, chapter, tasks):
    # Find the Task log table for the given chapter
    node = None
    for n in doc["nodes"]:
        if n["title"] == f"{chapter}: Task log":
            node = n
            break

    if not node:
        return "Task log node not found"

    rows = node["table"]["rows"]
    cols = node["table"]["columns"]

    task_data = {task: [] for task in tasks}
    for row in rows:
        # The task ID is in the 'task' column
        try:
            t_id = row[cols.index('task')]
            if t_id in tasks:
                task_data[t_id].append(row)
        except (ValueError, IndexError):
            continue

    return task_data

